import{_ as e,o as l,c as d,af as a}from"./chunks/framework.BSym9njW.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"zh/00-environment/npu-troubleshooting.md","filePath":"zh/00-environment/npu-troubleshooting.md","lastUpdated":1789547203000}'),o={name:"zh/00-environment/npu-troubleshooting.md"};function s(n,t,i,r,c,m){return l(),d("div",null,[...t[0]||(t[0]=[a(`<h2 id="fastflowlm-lemonade-排错" tabindex="-1">FastFlowLM / Lemonade 排错 <a class="header-anchor" href="#fastflowlm-lemonade-排错" aria-label="Permalink to &quot;FastFlowLM / Lemonade 排错&quot;">​</a></h2><p>NPU 与 Lemonade 环境、部署中的常见问题。GPU 的 ROCm / HIP 问题仍见 <a href="/hello-rocm/zh/00-environment/#三校验安装">00-Environment 校验</a>。</p><table tabindex="0"><thead><tr><th style="text-align:left;">现象</th><th style="text-align:left;">处理</th></tr></thead><tbody><tr><td style="text-align:left;">没有 <code>flm</code></td><td style="text-align:left;">按 <a href="./fastflowlm">FastFlowLM 环境</a> 装 deb，然后 <strong>reboot</strong></td></tr><tr><td style="text-align:left;"><code>No NPU device found</code></td><td style="text-align:left;">查 <code>/dev/accel/accel0</code> 与 <code>render</code> 组；<code>sudo usermod -aG render,video $USER</code> 后重新登录</td></tr><tr><td style="text-align:left;">SVA bind <code>-19</code></td><td style="text-align:left;">cmdline 必须 <code>amd_iommu=on iommu=pt</code>，改 GRUB 后 reboot</td></tr><tr><td style="text-align:left;"><code>No such device with index &#39;0&#39;</code></td><td style="text-align:left;">当前 shell <strong>不要</strong>带 ROCm XRT：<code>unset ROCM_PATH HIP_PATH LD_LIBRARY_PATH</code>；再查 <code>xrt-smi examine</code></td></tr><tr><td style="text-align:left;">只换 1.1 固件、NPU 消失</td><td style="text-align:left;">驱动+固件必须成对；用 PPA 的 <code>amdxdna-dkms</code>，不要只刷 firmware</td></tr><tr><td style="text-align:left;"><code>modinfo amdxdna</code> 不在 <code>updates/dkms</code></td><td style="text-align:left;">未 reboot，或仍在用内核树内旧模块</td></tr><tr><td style="text-align:left;"><code>ulimit -l</code> 不是 unlimited</td><td style="text-align:left;">写入 <code>limits.conf</code> 后重新登录；当前会话可试 <code>ulimit -l unlimited</code></td></tr><tr><td style="text-align:left;">NPU 与大 GTT 配方冲突</td><td style="text-align:left;">GTT 常用 <code>amd_iommu=off</code>，和 FLM 互斥</td></tr><tr><td style="text-align:left;">没有 <code>lemonade</code></td><td style="text-align:left;"><code>sudo apt install lemonade-server</code></td></tr><tr><td style="text-align:left;"><code>status</code> 连不上 13305</td><td style="text-align:left;">看进程 <code>/usr/bin/lemond</code>；<code>ss -tlnp | grep 13305</code>；<code>sudo systemctl start lemond</code></td></tr><tr><td style="text-align:left;">13305 停不掉</td><td style="text-align:left;"><code>sudo systemctl stop lemond</code>（单位名不是 lemonade-server）</td></tr><tr><td style="text-align:left;"><code>llamacpp:rocm</code> = kernel missing support</td><td style="text-align:left;">改用 <code>llamacpp:vulkan</code>；ROCm 见 <a href="https://lemonade-server.ai/gfx1151_linux.html" target="_blank" rel="noreferrer">gfx1151 Linux</a></td></tr><tr><td style="text-align:left;"><code>flm:npu</code> 未装 / GitHub 超时</td><td style="text-align:left;">国内拉 FLM tar.gz 常失败。NPU 用原生 <a href="./fastflowlm">FastFlowLM</a></td></tr><tr><td style="text-align:left;"><code>load gemma4-it:e4b</code> 404</td><td style="text-align:left;">systemd <code>lemond</code> 的 ProtectHome 看不到用户 FLM 缓存；走 8219</td></tr><tr><td style="text-align:left;">Lemonade 和 <code>flm serve</code> 抢 NPU</td><td style="text-align:left;">先 <code>lemonade unload</code> + <code>sudo systemctl stop lemond</code> 或 <code>pkill -x flm</code>，只留一路</td></tr><tr><td style="text-align:left;">503</td><td style="text-align:left;">NPU 队列满，降并发或加大 <code>--q-len</code></td></tr><tr><td style="text-align:left;">和 GPU 大模型一起 OOM</td><td style="text-align:left;">统一内存；先停 vLLM / Ollama / 大 GGUF，再只起 FLM</td></tr><tr><td style="text-align:left;"><code>flm validate</code> 在沙箱里失败</td><td style="text-align:left;">无 <code>/dev/accel</code> 属正常；在真实终端跑</td></tr></tbody></table><p>日志位置：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># FastFlowLM 前台日志，或你重定向的文件</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">journalctl</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -u</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> lemond</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -n</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;"> 80</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --no-pager</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div>`,5)])])}const g=e(o,[["render",s]]);export{p as __pageData,g as default};
